#include <vector>
#include <algorithm>

class Solution {
private:
    int ans = 0;
    std::pair<bool, int> dfs(int node, int parent, const std::vector<std::vector<int>>& g, const std::vector<int>& colors) {
        bool isSame = true;
        int size = 1;
        for (int neighbor : g[node]) {
            if (neighbor != parent) {
                auto child = dfs(neighbor, node, g, colors);
                if (!child.first || colors[neighbor] != colors[node]) {
                    isSame = false;
                }
                size += child.second;
            }
        }
        if (isSame) {
            ans = std::max(ans, size);
        }
        return {isSame, size};
    }
public:
    int maximumSubtreeSize(std::vector<std::vector<int>>& edges, std::vector<int>& colors) {
        int n = colors.size();
        std::vector<std::vector<int>> g(n);
        for (const auto& e : edges) {
            g[e[0]].push_back(e[1]);
            g[e[1]].push_back(e[0]);
        }
        ans = 0;
        dfs(0, -1, g, colors);
        return ans;
    }
};

import java.util.ArrayList;
import java.util.List;

class Solution {
    private int ans = 0;

    static class Result {
        boolean isSame;
        int size;
        Result(boolean isSame, int size) {
            this.isSame = isSame;
            this.size = size;
        }
    }

    private Result dfs(int node, int parent, List<List<Integer>> g, int[] colors) {
        boolean isSame = true;
        int size = 1;
        for (int neighbor : g.get(node)) {
            if (neighbor != parent) {
                Result child = dfs(neighbor, node, g, colors);
                if (!child.isSame || colors[neighbor] != colors[node]) {
                    isSame = false;
                }
                size += child.size;
            }
        }
        if (isSame) {
            ans = Math.max(ans, size);
        }
        return new Result(isSame, size);
    }

    public int maximumSubtreeSize(int[][] edges, int[] colors) {
        int n = colors.length;
        List<List<Integer>> g = new ArrayList<>();
        for (int i = 0; i < n; i++) g.add(new ArrayList<>());
        for (int[] e : edges) {
            g.get(e[0]).add(e[1]);
            g.get(e[1]).add(e[0]);
        }
        ans = 0;
        dfs(0, -1, g, colors);
        return ans;
    }
}

var maximumSubtreeSize = function(edges, colors) {
    const n = colors.length;
    const g = Array.from({ length: n }, () => []);
    for (const [u, v] of edges) {
        g[u].push(v);
        g[v].push(u);
    }
    let ans = 0;
    function dfs(node, parent) {
        let isSame = true;
        let size = 1;
        for (const neighbor of g[node]) {
            if (neighbor !== parent) {
                const child = dfs(neighbor, node);
                if (!child.isSame || colors[neighbor] !== colors[node]) {
                    isSame = false;
                }
                size += child.size;
            }
        }
        if (isSame) {
            ans = Math.max(ans, size);
        }
        return { isSame, size };
    }
    dfs(0, -1);
    return ans;
};
